      const fadeGrad = ctx.createLinearGradient(cx, boxY, cx, cy);
      fadeGrad.addColorStop(0, "rgba(0,0,0,0)");
      fadeGrad.addColorStop(1, `rgba(0,0,0,${this.domeBottomFade})`);
      ctx.fillStyle = fadeGrad;
